<script setup lang="ts">
import type { GuideContent } from '~~/shared/guide'

type Submission={id:string;state:'awaiting_review'|'published'|'rejected';content:GuideContent;moderator_note:string|null;created_at:string;reviewed_at:string|null;slug:string|null;annotations:Array<{quote:string;note:string;created_at:string}>}
const {data,error}=await useFetch<Submission[]>('/api/submissions')
const labels={awaiting_review:'Waiting for review',published:'Published',rejected:'Changes requested'} as const
const tone={awaiting_review:'review',published:'published',rejected:'changes'} as const
const date=(value:string)=>new Intl.DateTimeFormat('en-NG',{day:'numeric',month:'short',year:'numeric'}).format(new Date(value.includes('T')?value:value.replace(' ','T')+'Z'))
useSeoMeta({title:'My guides — WikiHowNaija'})
</script>

<template><section class="my-guides-page"><header class="my-guides-heading"><div><p class="eyebrow">Your contributions</p><h1>My guides</h1><p>See what is waiting, what was published, and what an editor asked you to change.</p></div><NuxtLink class="button secondary" to="/write"><UIcon name="i-lucide-plus" class="button-icon"/>Write a guide</NuxtLink></header><div v-if="error" class="notice"><p>Sign in to see your guides.</p><NuxtLink class="button secondary" :to="{path:'/login',query:{next:'/my-guides'}}">Sign in</NuxtLink></div><div v-else-if="!data?.length" class="empty"><h2>You have not sent a guide yet.</h2><p>Share something you have done and can explain clearly.</p><NuxtLink class="button secondary" to="/write">Write your first guide</NuxtLink></div><ol v-else class="submission-list"><li v-for="item in data" :key="item.id" class="submission-card"><div class="submission-card-title"><div><em class="status-pill" :class="`is-${tone[item.state]}`">{{labels[item.state]}}</em><h2>{{item.content.title}}</h2><p>{{item.content.summary}}</p></div><span>{{date(item.reviewed_at||item.created_at)}}</span></div><div v-if="item.moderator_note" class="submission-feedback"><strong>Editor’s note</strong><p>{{item.moderator_note}}</p></div><div v-if="item.annotations.length" class="submission-feedback"><strong>Notes on the guide</strong><ul><li v-for="annotation in item.annotations" :key="annotation.quote+annotation.created_at"><q>{{annotation.quote}}</q><p>{{annotation.note}}</p></li></ul></div><div class="submission-card-actions"><NuxtLink v-if="item.slug" class="button secondary" :to="`/guides/${item.slug}`">Read published guide</NuxtLink><NuxtLink v-if="item.state==='rejected'" class="button secondary" :to="`/write?retry=${item.id}`">Make the requested changes</NuxtLink><NuxtLink v-else-if="item.slug" class="button secondary" :to="`/write?edit=${item.slug}`">Suggest an update</NuxtLink></div></li></ol></section></template>
